  "check_code": "import sqlite3
from pathlib import Path


def _db(ws):
    return Path(ws).parent / "system" / "brent_sharepoint_kb" / "state.db"


def check_current_training_gate_link(ws):
    con = sqlite3.connect(_db(ws))
    con.row_factory = sqlite3.Row
    rows = con.execute(
        """SELECT document_id, version_id, linked_entity_type, linked_entity_id,
                  link_type, source_system_slug, created_by_person_id, access_note
           FROM document_links
           WHERE document_id=? AND version_id=? AND linked_entity_type=?
             AND linked_entity_id=? AND link_type=?""",
        ("DOC-CRM-TRAIN-2019-017", "VER-CRM-TRAIN-2019-1-0", "readiness_gate",
         "GATE-REL19-04", "evidences"),
    ).fetchall()
    con.close()
    if len(rows) != 1:
        return {"score": 0, "detail": f"Expected exactly one current training gate link; found {len(rows)}."}
    row = dict(rows[0])
    expected = {
        "document_id": "DOC-CRM-TRAIN-2019-017",
        "version_id": "VER-CRM-TRAIN-2019-1-0",
        "linked_entity_type": "readiness_gate",
        "linked_entity_id": "GATE-REL19-04",
        "link_type": "evidences",
        "source_system_slug": "brent_powerbi_mart",
        "created_by_person_id": "PER-EMILY-CARTER",
    }
    for key, value in expected.items():
        if row.get(key) != value:
            return {"score": 0, "detail": f"{key} is {row.get(key)!r}, expected {value!r}."}
    note = (row.get("access_note") or "").lower()
    if "current" not in note or "role-based" not in note or "training" not in note or "evidence" not in note:
        return {"score": 0, "detail": "Access note does not identify current role-based training evidence."}
    return {"score": 1, "detail": "Current published training version evidences GATE-REL19-04 with the required controls."}


def check_historical_integrity(ws):
    con = sqlite3.connect(_db(ws))
    con.row_factory = sqlite3.Row
    doc = con.execute(
        "SELECT approval_status, library_view_status, effective_date, expiry_date FROM knowledge_documents WHERE document_id=?",
        ("DOC-CRM-TRAIN-2018-003",),
    ).fetchone()
    version = con.execute(
        "SELECT version_status, effective_from, effective_to, supersedes_version_id FROM document_versions WHERE version_id=?",
        ("VER-CRM-TRAIN-2018-3-0",),
    ).fetchone()
    old_links = con.execute(
        "SELECT COUNT(*) FROM document_links WHERE version_id=? AND linked_entity_type='readiness_gate' AND linked_entity_id='GATE-REL19-04'",
        ("VER-CRM-TRAIN-2018-3-0",),
    ).fetchone()[0]
    con.close()
    ok = (
        doc is not None
        and dict(doc) == {
            "approval_status": "Superseded",
            "library_view_status": "Current",
            "effective_date": "2018-03-05",
            "expiry_date": "2019-03-17",
        }
        and version is not None
        and dict(version) == {
            "version_status": "Superseded",
            "effective_from": "2018-03-05",
            "effective_to": "2019-03-17",
            "supersedes_version_id": None,
        }
        and old_links == 0
    )
    return {"score": 1 if ok else 0, "detail": "Superseded 2018 metadata/version and absence of the forbidden gate link are intact." if ok else "Historical training metadata or forbidden-link state was changed."}
